input.sparql:
SELECT ?point ?class ?series WHERE {
  ?point ref:hasExternalReference ?x .
  ?x ref:hasTimeseriesId ?series .
  ?point a ?class
  FILTER (str(?point) LIKE "%Z01%")
}

SELECT ?point ?class ?series ?zone ?zname WHERE {
  ?point ref:hasExternalReference ?x .
  ?x ref:hasTimeseriesId ?series .
  OPTIONAL { ?point a ?class }
  OPTIONAL { ?zone brick:hasProperty ?point }
  OPTIONAL { ?zone rdfs:label ?zname }
  FILTER (str(?point) LIKE "%Zone%" && str(?point) LIKE "%Temperature%")
}

PREFIX brick: <http://brickexemplar.net/vocab#> SELECT ?point ?class ?series ?zone WHERE {
  ?point ref:hasExternalReference ?x .
  ?x ref:hasTimeseriesId ?series .
  OPTIONAL { ?point a ?class }
  OPTIONAL { ?zone brick:hasProperty ?point }
  FILTER (str(?point) LIKE "%Zone%" && str(?point) LIKE "%Temperature%")
} LIMIT 200

